import {
  Body,
  Button,
  Container,
  Head,
  Heading,
  Html,
  Img,
  Link,
  Preview,
  Section,
  Text,
} from "@react-email/components";
import * as React from "react";

type ConsultationReceivedEmailProps = {
  brandName?: string;
  recipientName?: string;
  recipientEmail?: string;
  previewUrl?: string;
  /** Trusted QR markup generated by the sender; empty for legacy deliveries. */
  previewQrHtml?: string;
  whatsappUrl?: string;
  supportEmail?: string | null;
  submittedAt?: string;
  submissionId?: string;
};

const shell = {
  backgroundColor: "#09111f",
  backgroundImage:
    "radial-gradient(circle at top, rgba(52, 211, 153, 0.12), transparent 32%), linear-gradient(180deg, #09111f 0%, #050913 100%)",
  fontFamily: '"Helvetica Neue", Arial, sans-serif',
  margin: "0",
  padding: "32px 16px",
} as const;

const card = {
  backgroundColor: "#0f1728",
  border: "1px solid #21314f",
  borderRadius: "24px",
  boxShadow: "0 24px 80px rgba(0, 0, 0, 0.35)",
  overflow: "hidden",
} as const;

const section = {
  padding: "32px",
} as const;

const brandLogo = {
  display: "block",
  height: "40px",
  margin: "0 10px 0 0",
  width: "40px",
} as const;

const hero = {
  background:
    "linear-gradient(135deg, rgba(56, 189, 248, 0.18), rgba(16, 185, 129, 0.14))",
  borderBottom: "1px solid #21314f",
} as const;

const wordmark = {
  color: "#ffffff",
  fontFamily: '"Space Grotesk", "Helvetica Neue", Arial, sans-serif',
  fontSize: "29px",
  fontWeight: "600",
  letterSpacing: "-1px",
  lineHeight: "1.2",
} as const;

const wordmarkAmpersand = {
  color: "#f4b578",
} as const;

const wordmarkEnergy = {
  color: "#bed0d0",
  fontSize: "11px",
  fontWeight: "500",
  letterSpacing: "0.2px",
} as const;

const h1 = {
  color: "#e6f3ff",
  fontSize: "28px",
  fontWeight: "700",
  lineHeight: "1.25",
  margin: "0 0 8px",
} as const;

const bodyText = {
  color: "#b8c7dd",
  fontSize: "15px",
  lineHeight: "1.8",
  margin: "0 0 16px",
} as const;

const infoBox = {
  backgroundColor: "#121d33",
  border: "1px solid #223251",
  borderRadius: "16px",
  padding: "20px",
  margin: "24px 0",
} as const;

const metaLabel = {
  color: "#7dd3fc",
  fontSize: "14px",
  fontWeight: "700",
  letterSpacing: "0.08em",
  margin: "0 0 8px",
  textTransform: "uppercase" as const,
} as const;

const finePrint = {
  color: "#7e8ca6",
  fontSize: "12px",
  lineHeight: "1.7",
  margin: "0",
} as const;

const cta = {
  backgroundColor: "#007a87",
  borderRadius: "999px",
  color: "#ffffff",
  fontSize: "15px",
  fontWeight: "700",
  padding: "14px 22px",
  textDecoration: "none",
} as const;

export default function ConsultationReceivedEmail({
  brandName = "Sol & Tide Energy",
  recipientName = "{{{RECIPIENT_NAME}}}",
  recipientEmail = "{{{RECIPIENT_EMAIL}}}",
  previewUrl = "{{{PREVIEW_URL}}}",
  previewQrHtml,
  whatsappUrl,
  supportEmail = "{{{SUPPORT_EMAIL}}}",
  submittedAt = "18 Sep 2026 · 2:41 AM AST",
  submissionId = "{{{SUBMISSION_ID}}}",
}: ConsultationReceivedEmailProps) {
  return (
    <Html lang="en">
      <Head>
        <style>{`@media only screen and (max-width: 480px) { .email-section { padding: 24px 16px !important; } .email-shell { padding: 16px 8px !important; } .email-cta { box-sizing: border-box !important; display: block !important; text-align: center !important; padding: 14px 16px !important; } }`}</style>
      </Head>
      <Preview>{`${brandName}: your preliminary quote is ready. View the details using the link below.`}</Preview>
      <Body className="email-shell" style={shell}>
        <Container style={card}>
          <Section className="email-section" style={{ ...section, ...hero }}>
            <table
              cellPadding="0"
              cellSpacing="0"
              role="presentation"
              style={{ margin: "0 auto 24px" }}
            >
              <tbody>
                <tr>
                  <td style={{ verticalAlign: "middle" }}>
                    <Img
                      alt="Sol & Tide Energy"
                      height="40"
                      src="https://www.solortide.com/icon.svg"
                      style={brandLogo}
                      width="40"
                    />
                  </td>
                  <td style={{ verticalAlign: "middle" }}>
                    <span style={wordmark}>
                      Sol <span style={wordmarkAmpersand}>&amp;</span> Tide{" "}
                      <span style={wordmarkEnergy}>Energy</span>
                    </span>
                  </td>
                </tr>
              </tbody>
            </table>
            <Text style={bodyText}>
              Hello <strong>{recipientName || recipientEmail}</strong>,
            </Text>
            <Heading as="h1" style={h1}>
              Your preliminary quote is ready
            </Heading>
            <Text style={{ ...bodyText, margin: "0" }}>
              Our team has prepared a rough quote based on your submission.
              Please use the link below to view your preliminary quote details.
            </Text>
          </Section>

          <Section className="email-section" style={section}>
            <Section style={{ margin: "0 0 28px", textAlign: "center" }}>
              <Button className="email-cta" href={previewUrl} style={cta}>
                View your preliminary quote
              </Button>
            </Section>
            {previewQrHtml && <div dangerouslySetInnerHTML={{ __html: previewQrHtml }} />}
            {whatsappUrl && <Section style={{ margin: "0 0 28px", textAlign: "center" }}>
              <Button className="email-cta" href={whatsappUrl} style={{ ...cta, backgroundColor: "#128C7E" }}>
                <Img alt="" src="https://www.solortide.com/contact/whatsapp-logo-white-v1.png" width="22" height="22" style={{ display: "inline-block", verticalAlign: "middle", marginRight: "9px" }} />
                Chat on WhatsApp
              </Button>
            </Section>}
            <Section style={infoBox}>
              <Text style={{ ...metaLabel, textAlign: "center" }}>Submission ID</Text>
              <Text style={{ ...bodyText, margin: "0 0 22px", paddingBottom: "20px", borderBottom: "1px solid #33435c", color: "#f5c875", fontSize: "26px", fontWeight: "700", overflowWrap: "anywhere", textAlign: "center" }}>
                {submissionId}
              </Text>
              <Text style={metaLabel}>Submitted at</Text>
              <Text style={{ ...bodyText, margin: "0 0 12px" }}>
                {submittedAt}
              </Text>
              <Text style={{ ...finePrint, margin: "16px 0 0" }}>Local time · Atlantic Standard Time (UTC−4)</Text>
            </Section>

            <Text style={bodyText}>
              If you would like to add information or need further assistance,
              simply reply to this email.
              {supportEmail ? (
                <>
                  You can also contact us at{" "}
                  <Link href={`mailto:${supportEmail}`}>{supportEmail}</Link>.
                </>
              ) : null}
            </Text>

            <Text style={finePrint}>
              This is an automated email confirming that we have received your
              consultation.
            </Text>
          </Section>
        </Container>
      </Body>
    </Html>
  );
}
